"use client";
import {create} from "zustand";
type State={
  progress:number;
  velocity:number;
  act:number;
  selected:string|null;
  setMotion:(progress:number,velocity:number)=>void;
  setAct:(act:number)=>void;
  select:(selected:string|null)=>void;
};
export const useArchive=create<State>((set)=>({
  progress:0,velocity:0,act:0,selected:null,
  setMotion:(progress,velocity)=>set({progress,velocity}),
  setAct:(act)=>set({act}),
  select:(selected)=>set({selected})
}));

