"use client";
import {Canvas} from "@react-three/fiber";
import {Suspense} from "react";
import {ACESFilmicToneMapping,PCFSoftShadowMap,SRGBColorSpace} from "three";
import {ArchiveWorld} from "./ArchiveWorld";
import {ArchiveCamera} from "./ArchiveCamera";
import {ArchivePostFX} from "./ArchivePostFX";

export function ArchiveCanvas(){
  const automated=typeof window!=="undefined"&&new URLSearchParams(location.search).get("automation")==="1";
  return <div className="canvas-shell">
    <Canvas
      shadows={!automated}
      dpr={automated?[0.6,0.8]:[1,1.65]}
      camera={{fov:44,near:.06,far:220,position:[0,1.65,9]}}
      gl={{antialias:!automated,powerPreference:"high-performance",alpha:false}}
      onCreated={({gl})=>{gl.toneMapping=ACESFilmicToneMapping;gl.outputColorSpace=SRGBColorSpace;gl.shadowMap.type=PCFSoftShadowMap;}}
    >
      <Suspense fallback={null}>
        <ArchiveWorld automated={automated}/>
        <ArchiveCamera/>
        {!automated?<ArchivePostFX/>:null}
      </Suspense>
    </Canvas>
  </div>;
}

