"use client";
import {useFrame} from "@react-three/fiber";
import {CatmullRomCurve3,MathUtils,Vector3} from "three";
import {useMemo,useRef} from "react";
import {useArchive} from "@/store/archive";

const points=[
  [0,1.6,9],
  [0,1.62,1],
  [-.25,1.68,-18],
  [.2,1.7,-42],
  [-.15,1.74,-66],
  [0,1.82,-90],
  [0,2.05,-112],
] as const;

export function ArchiveCamera(){
  const progress=useArchive(s=>s.progress);
  const velocity=useArchive(s=>s.velocity);
  const setAct=useArchive(s=>s.setAct);
  const tRef=useRef(0);
  const look=useRef(new Vector3(0,1.5,0));
  const path=useMemo(()=>new CatmullRomCurve3(points.map(([x,y,z])=>new Vector3(x,y,z)),false,"catmullrom",.45),[]);
  useFrame(({camera,pointer},delta)=>{
    tRef.current=MathUtils.damp(tRef.current,progress,7.2,delta);
    const t=MathUtils.clamp(tRef.current,0,1);
    const p=path.getPointAt(t);
    const ahead=path.getPointAt(Math.min(1,t+.012+Math.min(Math.abs(velocity)*.00006,.008)));
    camera.position.x=MathUtils.damp(camera.position.x,p.x+pointer.x*.13,8,delta);
    camera.position.y=MathUtils.damp(camera.position.y,p.y+pointer.y*.055,8,delta);
    camera.position.z=MathUtils.damp(camera.position.z,p.z,9,delta);
    look.current.x=MathUtils.damp(look.current.x,ahead.x+pointer.x*.12,9,delta);
    look.current.y=MathUtils.damp(look.current.y,ahead.y+pointer.y*.05,9,delta);
    look.current.z=MathUtils.damp(look.current.z,ahead.z-2.2,10,delta);
    camera.lookAt(look.current);
    setAct(Math.min(4,Math.floor(t*5)));
  });
  return null;
}

