"use client";
import {Bloom,EffectComposer,Noise,Vignette} from "@react-three/postprocessing";
import {BlendFunction} from "postprocessing";
export function ArchivePostFX(){
  return <EffectComposer multisampling={4}>
    <Bloom intensity={.14} luminanceThreshold={1.1} luminanceSmoothing={.3} mipmapBlur/>
    <Noise opacity={.012} blendFunction={BlendFunction.SOFT_LIGHT}/>
    <Vignette eskil={false} offset={.2} darkness={.48}/>
  </EffectComposer>;
}

