"use client";
import {Clone,useGLTF} from "@react-three/drei";
import {assetPath} from "@/lib/assetPath";
import type {ThreeElements} from "@react-three/fiber";

export function ModelAsset({file,...props}:{file:string}&ThreeElements["group"]){
  const gltf=useGLTF(assetPath("/assets/models/"+file));
  return <group {...props}><Clone object={gltf.scene} castShadow receiveShadow/></group>;
}
